module pcb_core_box() {
  cube([pcb_L - 2*corner_R, pcb_W - 2*corner_R, pcb_T], center=true);
}

module corner_cyl(pos) {
  translate(pos)
    cylinder(r=corner_R, h=pcb_T, center=true);
}

