    standoff([-pcb_L/2 + hole_edge_offset, -pcb_W/2 + hole_edge_offset, -pcb_T/2 - standoff_h/2 + standoff_overlap]);
    standoff([pcb_L/2 - hole_edge_offset, -pcb_W/2 + hole_edge_offset, -pcb_T/2 - standoff_h/2 + standoff_overlap]);
  }
}

// Final Model
module complete_model() {
  union() {
    pcb_board();
    connectors();
    chips();
    heatsinks();
    silkscreen_text();
    standoffs();
  }
