module silk_border_inner_cut() {
  translate([0, 0, pcb_T/2 + silk_T/2 - connect_overlap])
    cube([pcb_L - 2*(silk_margin + trace_W), pcb_W - 2*(silk_margin + trace_W), silk_T + hole_clearance_Z], center=true);
}

module copper_pad(pos) {
