    cylinder(r=pad_D/2, h=copper_T, center=true);
}

module copper_trace() {
  translate([-pcb_L/2 + mount_edge_offset + 2*pad_pitch + trace_L/2 - connect_overlap, 0, pcb_T/2 + copper_T/2 - connect_overlap])
    cube([trace_L, trace_W, copper_T], center=true);
