// Operations
module rounded_corners() {
  hull() {
    pcb_corner_cyl([pcb_L/2 - corner_R, pcb_W/2 - corner_R, 0]);
    pcb_corner_cyl([-pcb_L/2 + corner_R, pcb_W/2 - corner_R, 0]);
    pcb_corner_cyl([-pcb_L/2 + corner_R, -pcb_W/2 + corner_R, 0]);
    pcb_corner_cyl([pcb_L/2 - corner_R, -pcb_W/2 + corner_R, 0]);
