    mount_hole([pcb_L/2 - mount_edge_offset, -pcb_W/2 + mount_edge_offset, 0]);
    mount_hole([-pcb_L/2 + mount_edge_offset, pcb_W/2 - mount_edge_offset, 0]);
    mount_hole([pcb_L/2 - mount_edge_offset, pcb_W/2 - mount_edge_offset, 0]);
  }
}

module edge_connector_cutouts() {
  edge_connector_cutout([pcb_L/2 - edge_cutout_D/2, 0, 0]);
}

module pcb_body() {
  difference() {
    rounded_corners();
    mounting_holes();
    edge_connector_cutouts();
  }
}

module silkscreen_markings() {
  difference() {
