    cube([pcb_L, pcb_W, pcb_T], center=true);
    union() {
      translate([-pcb_L/2 + hole_edge_margin, -pcb_W/2 + hole_edge_margin, 0])
        cylinder(h=pcb_T + hole_clearance_z, r=hole_d/2, center=true);
