    translate([-0.5*pad_pitch, pad_row_y, pcb_T/2 + pad_T/2 - overlap])
      cube([pad_L, pad_W, pad_T], center=true);
    translate([0.5*pad_pitch, pad_row_y, pcb_T/2 + pad_T/2 - overlap])
      cube([pad_L, pad_W, pad_T], center=true);
    translate([1.5*pad_pitch, pad_row_y, pcb_T/2 + pad_T/2 - overlap])
