      cube([outline_L - 2*outline_line_W, outline_W - 2*outline_line_W, outline_T + overlap], center=true);
  }
}

// Complete PCB
module pcb_complete() {
  union() {
    pcb_body_with_holes_and_chamfer();
    silkscreen_markings();
    copper_pads();
    components_outline();
  }
}

