outer_diameter_mm = 10.0; //[5.0:20.0:0.5]
inner_diameter_mm = 5.0; //[2.5:10.0:0.5]
lug_width_mm = 6.0; //[3.0:12.0:0.5]
overall_length_mm = 20.0; //[10.0:40.0:1]
crimp_length_mm = 0.0; //[0.0:30.0:0.5]
