  }
}

// Ring Terminal Assembly
module ring_terminal_assembly() {
  union() {
    ring_terminal();
    if (terminal_type == 1) {
      translate([0, 0, 0]) crimp_barrel();
    }
  }
}

// Final Assembly
module assembly() {
  ring_terminal_assembly();
}

assembly();

