      }
      // Transition
      translate([0, -(overall_length_mm - outer_diameter_mm / 2) + transition_length_mm / 2 - overlap_mm, thickness_mm / 2])
        cube([tab_width_mm, transition_length_mm, thickness_mm], center=true);
    }
  }
}

// Assembly
module assembly() {
  ring_terminal();
  ring_terminal_assembly();
}

