      translate([(-t - (bend_r - t)) + t/2, 0, -height + t + (height - 2*bend_r)/2])
        cube([t, hook_y, height - 2*bend_r], center=true);
      translate([(-t - (bend_r - t)) + bend_r + (hook_x - bend_r)/2, 0, -t/2])
        cube([hook_x - bend_r, hook_y, t], center=true);

